432	        int points = 0;
433	        if (hasEmail()) {
434	            points += 2;
435	        }
436	        if (hasNoNamesakes()) {
437	            points += 1;
438	        }
439	        if (hasLargeHousehold()) {
440	            points += 2;
441	        }
442	        if (hasTenureBeyondOneYear()) {
443	            points += 3;
444	        }
445	        return points;
446	    }
