476	    /**
477	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
478	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
479	     * email presence so the check is never re-derived elsewhere.
480	     */
481	    private boolean hasEmail() {
482	        return this.email != null && !this.email.isEmpty();
483	    }
484	
485	    /**
486	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
487	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
488	     * not known, is treated as not unique.
489	     */
490	    private boolean hasNoNamesakes() {
491	        return this.namesakeCount != null && this.namesakeCount == 0;
492	    }
493	
494	    /**
495	     * Whether this owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. A newly created owner
496	     * (zero tenure) does not qualify; the threshold is crossed only once tenure grows beyond one year.
497	     */
498	    private boolean hasTenureBeyondOneYear() {
499	        return this.getTenureDays() > 365;
500	    }
501	
502	    /**
503	     * The owner's tenure in whole days: the number of days between the {@link #registrationDate} and
504	     * the current date, or {@code 0} when the registrationDate is not yet set (a newly created owner has
505	     * zero tenure). Never negative.
506	     */
507	    public long getTenureDays() {
508	        if (this.registrationDate == null) {
509	            return 0;
510	        }
511	        return Math.max(0, ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()));
512	    }
513	
514	    /**
515	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
516	     * otherwise {@code 'PHONE'}.
517	     */
518	    public String getContactPreference() {
519	        return hasEmail() ? "EMAIL" : "PHONE";
520	    }
521	
522	    /**
523	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
524	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
525	     * the national digits grouped into threes from the left separated by spaces,
526	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
527	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
528	     * E.164 form, or carries no known country code.
529	     */
530	    public String getTelephoneDisplay() {
531	        if (this.telephone == null || !this.telephone.startsWith("+")) {
532	            return this.telephone;
533	        }
534	        String digits = this.telephone.substring(1);
535	        String countryCode = countryCodeOf(digits);
536	        if (countryCode == null) {
537	            return this.telephone;
538	        }
539	        String national = digits.substring(countryCode.length());
540	        StringBuilder groups = new StringBuilder();
541	        for (int i = 0; i < national.length(); i += 3) {
542	            if (groups.length() > 0) {
543	                groups.append(' ');
544	            }
545	            groups.append(national, i, Math.min(i + 3, national.length()));
546	        }
547	        return "+" + countryCode + " " + groups;
548	    }
549	
550	    /**
551	     * The owner's identity key: the single derived value used for duplicate detection.
552	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
553	     * empty string when absent) and the householdId (or the empty string when the owner
554	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
555	     * Two owners are duplicates only when their whole identity keys are equal.
556	     */
557	    public String getIdentityKey() {
558	        String telephonePart = this.telephone == null ? "" : this.telephone;
559	        String emailPart = this.email == null ? "" : this.email;
560	        String householdPart = this.householdId == null ? "" : this.householdId;
561	        return telephonePart + "|" + emailPart + "|" + householdPart;
562	    }
563	
564	    protected Set<Pet> getPetsInternal() {
565	        if (this.pets == null) {
566	            this.pets = new HashSet<>();
567	        }
568	        return this.pets;
569	    }
570	
571	    protected void setPetsInternal(Set<Pet> pets) {
572	        this.pets = pets;
573	    }
574	
575	    public List<Pet> getPets() {
576	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
577	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
578	        return Collections.unmodifiableList(sortedPets);
579	    }
580	
581	    public void setPets(List<Pet> pets) {
582	        this.pets = new HashSet<>(pets);
583	    }
584	
585	    public void addPet(Pet pet) {
586	        getPetsInternal().add(pet);
587	        pet.setOwner(this);
588	    }
589	
590	    /**
591	     * Return the Pet with the given name, or null if none found for this Owner.
592	     *
593	     * @param name to test
594	     * @return true if pet name is already in use
595	     */
596	    public Pet getPet(String name) {
597	        return getPet(name, false);
598	    }
599	
600	    /**
601	     * Return the Pet with the given name, or null if none found for this Owner.
602	     *
603	     * @param name to test
604	     * @return true if pet name is already in use
605	     */
606	    public Pet getPet(String name, boolean ignoreNew) {
607	        name = name.toLowerCase();
608	        for (Pet pet : getPetsInternal()) {
609	            if (!ignoreNew || !pet.isNew()) {
610	                String compName = pet.getName();
611	                compName = compName.toLowerCase();
612	                if (compName.equals(name)) {
613	                    return pet;
614	                }
615	            }
616	        }
617	        return null;
618	    }
619	
620	    public Pet getPet(Integer petId) {
621	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
622	    }
623	
624	    @Override
625	    public String toString() {
626	        return new ToStringCreator(this)
627	
628	            .append("id", this.getId())
629	            .append("new", this.isNew())
630	            .append("lastName", this.getLastName())
631	            .append("firstName", this.getFirstName())
632	            .append("address", this.address)
633	            .append("city", this.city)
634	            .append("telephone", this.telephone)
635	            .append("email", this.email)
636	            .toString();
637	    }
638	}
